    emit("(*")
    emit("========================================================================================================================")
    emit("  LUMINA ADVANCED MARINE & OFFSHORE CYBER-PHYSICAL SYSTEMS GROUP — REFERENCE IMPLEMENTATION V7")
    emit("  SECTOR         : OFFSHORE MARINE & NAVAL AUTONOMY (TIER 1 CRITICAL INFRASTRUCTURE)")
    emit("  VESSEL TYPE    : DP CLASS 3 (DP3) ULTRA-DEEPWATER SEMI-SUBMERSIBLE DRILLING / CONSTRUCTION RIG")
    emit("  DISPLACEMENT   : 48,000 METRIC TONNES (48,000,000 kg) AT 21.0 m OPERATING DRAFT")
    emit("  PROPULSION     : 8 x 3.5 MW AZIMUTH DIESEL-ELECTRIC THRUSTERS (5200 kN TOTAL COMBINED BOLLARD PULL)")
    emit("  POWER PLANT    : 48.0 MW (8 x 6,000 kW DIESEL GENERATORS ACROSS 4 SPLIT SWITCHBOARDS A/B/C/D)")
    emit("  BALLAST SYSTEM : 4 x 1,500 m3/h HIGH-SPEED REVERSIBLE ANTI-HEELING & ANTI-TRIM PUMPS ACROSS 8 WING TANKS")
    emit("  CYBER-PHYSICAL : 8-DOF STATE-SPACE EKF WITH WAVE NOTCH FILTER, RECEDING HORIZON MPC OPTIMIZER,")
    emit("                   2oo3 TRIPLE MODULAR REDUNDANCY VOTING, AND DYNAMIC PMS BLACKOUT PRESERVATION")
    emit("  DETERMINISTIC  : Ts = 25.0 ms REAL-TIME HIGH-INTEGRITY TASK CYCLE (40 Hz EXECUTION RATE)")
    emit("  STANDARDS      : IMO MSC/Circ.645 & 1580 (DP Class 3), DNV-GL DYNPOS-AUTRO, IEC 61508 SIL-3, ISA-18.2")
    emit("========================================================================================================================")
    emit("*)")
    emit("")
    emit("VAR_INPUT")
    emit("    (* ================================================================================= *)")
    emit("    (* 1. MASTER DIGITAL SUPERVISORY COMMANDS & OPERATOR INTERLOCKS                      *)")
    emit("    (* ================================================================================= *)")
    emit("    bEnableSystem                   : BOOL := FALSE;    (* Master Execution Permissive (Hardware Run Enable) *)")
    emit("    bEmergencyEStopDP3              : BOOL := TRUE;     (* Dual-Channel Fail-Safe DP3 Master Emergency Stop Permissive (Active High OK) *)")
