    emit("    bAntiTrimActiveRequest          : BOOL := FALSE;    (* Longitudinal Ballast Hydraulic Anti-Trim Leveling Request *)")
    emit("    bThrusterBiasRequest            : BOOL := FALSE;    (* Internal Thruster Counter-Biasing for Azimuth Backlash Elimination *)")
    emit("    bEmergencyDisconnectRequest     : BOOL := FALSE;    (* Marine Drilling Riser Emergency Quick-Release Drive-Off Trigger *)")
    emit("    bPMSFastShedRequest             : BOOL := FALSE;    (* Power Management Fast Load Shedding Manual Force Permissive *)")
    emit("")
    emit("    (* ================================================================================= *)")
    emit("    (* 2. TARGET SETPOINTS & POSITIONING TOLERANCE CONSTRAINTS                           *)")
    emit("    (* ================================================================================= *)")
    emit("    rSurgeSetpoint_m                : REAL := 0.0;      (* Desired Earth-Fixed Easting / Surge Position Setpoint [m] *)")
