    emit("    rHeadingSetpoint_deg            : REAL := 0.0;      (* Desired Vessel Compass Heading Angle Setpoint [deg] *)")
    emit("    rMaxSpeedSurge_mps              : REAL := 1.25;     (* Maximum Allowable Linear Surge Velocity Limit [m/s] *)")
    emit("    rMaxSpeedSway_mps               : REAL := 1.00;     (* Maximum Allowable Linear Sway Velocity Limit [m/s] *)")
    emit("    rMaxRateYaw_dps                 : REAL := 1.50;     (* Maximum Allowable Rotational Yaw Rate Limit [deg/s] *)")
