    emit("    rMRU2_YawRate_dps               : REAL := 0.0;      (* MRU Unit 2 Angular Yaw Rate Gyro Feedback [deg/s] *)")
    emit("    bMRU2_Valid                     : BOOL := TRUE;     (* MRU Unit 2 Built-In-Test Hardware Healthy Bit *)")
    emit("    rMRU3_Roll_deg                  : REAL := 0.0;      (* MRU Unit 3 Calibrated Transverse Roll Angle [deg] *)")
    emit("    rMRU3_Pitch_deg                 : REAL := 0.0;      (* MRU Unit 3 Calibrated Longitudinal Pitch Angle [deg] *)")
    emit("    rMRU3_Heave_m                   : REAL := 0.0;      (* MRU Unit 3 Calibrated Vertical Heave Displacement [m] *)")
    emit("    rMRU3_RollRate_dps              : REAL := 0.0;      (* MRU Unit 3 Angular Roll Rate Gyro Feedback [deg/s] *)")
