    emit("    rWindSpeed_Anemo3_mps           : REAL := 0.0;      (* Ultrasonic Anemometer 3 Relative Wind Velocity [m/s] *)")
    emit("    rWindDir_Anemo3_deg             : REAL := 0.0;      (* Ultrasonic Anemometer 3 Relative Wind Direction [deg] *)")
