    emit("    rBallastLevel_TK6_MidStbdAft_m  : REAL := 0.0;      (* Tank 6 Mid-Starboard-Aft Water Column Sounding Level [m] *)")
    emit("    rBallastPress_TK6_MidStbdAft_bar: REAL := 0.0;      (* Tank 6 Mid-Starboard-Aft Hydrostatic Bottom Pressure [bar] *)")
    emit("    rBallastLevel_TK7_AftPort_m     : REAL := 0.0;      (* Tank 7 Aft-Port Water Column Sounding Level [m] *)")
    emit("    rBallastPress_TK7_AftPort_bar   : REAL := 0.0;      (* Tank 7 Aft-Port Hydrostatic Bottom Pressure [bar] *)")
