    emit("    rEstimated_SwayPos_m            : REAL := 0.0;      (* Filtered Low-Frequency Earth-Fixed Sway Position [m] *)")
    emit("    rEstimated_Heading_deg          : REAL := 0.0;      (* Filtered True Compass Heading Orientation Angle [deg] *)")
    emit("    rEstimated_SurgeVel_mps         : REAL := 0.0;      (* Estimated Body-Fixed Linear Surge Velocity [m/s] *)")
    emit("    rEstimated_SwayVel_mps          : REAL := 0.0;      (* Estimated Body-Fixed Linear Sway Velocity [m/s] *)")
    emit("    rEstimated_YawRate_dps          : REAL := 0.0;      (* Estimated Body-Fixed Angular Yaw Rate Velocity [deg/s] *)")
    emit("    rEstimated_Roll_deg             : REAL := 0.0;      (* Estimated Quasi-Static Transverse Roll Angle [deg] *)")
